const { ApolloServer, gql } = require('apollo-server-express');
const express = require('express');
const { execSync } = require('child_process');
const fs = require('fs');
const path = require('path');

// GraphQL schema for a DevOps dashboard tool
const typeDefs = gql`
  type Query {
    healthCheck: HealthStatus!
    containerInfo(name: String!): ContainerInfo
    systemDiagnostics(target: String!): DiagnosticResult!
  }

  type HealthStatus {
    status: String!
    uptime: Float!
    hostname: String!
  }

  type ContainerInfo {
    name: String!
    status: String!
    image: String!
  }

  type DiagnosticResult {
    target: String!
    reachable: Boolean!
    latencyMs: Float
    rawOutput: String
  }
`;

const resolvers = {
  Query: {
    healthCheck: () => {
      return {
        status: 'healthy',
        uptime: process.uptime(),
        hostname: require('os').hostname()
      };
    },

    containerInfo: (_, { name }) => {
      // Validate container name format
      const sanitized = name.replace(/[^a-zA-Z0-9_-]/g, '');
      try {
        const result = execSync(`crictl inspect ${sanitized}`, { timeout: 5000 });
        const info = JSON.parse(result.toString());
        return { name: sanitized, status: info.status?.state || 'unknown', image: info.image || 'unknown' };
      } catch (e) {
        return { name: sanitized, status: 'not_found', image: 'N/A' };
      }
    },

    // Diagnostic resolver - performs network connectivity check
    systemDiagnostics: (_, { target }) => {
      // Basic format validation - allows hostnames, IPs, and common flags
      if (target.length > 128) {
        throw new Error('Target too long');
      }

      const startTime = Date.now();
      try {
        // VULNERABILITY: target is not properly sanitized before shell execution
        // An attacker can inject commands via the target parameter
        const output = execSync(`ping -c 2 -W 3 ${target}`, {
          timeout: 10000,
          encoding: 'utf-8'
        });
        const latency = Date.now() - startTime;
        return {
          target,
          reachable: true,
          latencyMs: latency,
          rawOutput: output.substring(0, 500)
        };
      } catch (err) {
        return {
          target,
          reachable: false,
          latencyMs: null,
          rawOutput: err.stderr ? err.stderr.substring(0, 500) : err.message
        };
      }
    }
  }
};

const app = express();

// Rate limiting middleware
app.use((req, res, next) => {
  // Simple in-memory rate limit
  next();
});

const server = new ApolloServer({
  typeDefs,
  resolvers,
  introspection: process.env.NODE_ENV !== 'production',
  plugins: [{
    requestDidStart() {
      return {
        didResolveOperation(ctx) {
          // Audit logging
          console.log(`[AUDIT] Operation: ${ctx.operationName || 'anonymous'}`);
        }
      };
    }
  }]
});

async function start() {
  await server.start();
  server.applyMiddleware({ app, path: '/graphql' });
  const port = process.env.PORT || 4000;
  app.listen(port, () => {
    console.log(`DevOps Dashboard API running on port ${port}`);
  });
}

start();
